<?php $parseLabels=['parsed'=>'مبلغ خوانده شد','failed'=>'خوانده نشد','ignored'=>'نادیده گرفته شد','pending'=>'در حال پردازش'];$matchLabels=['matched'=>'تطبیق موفق','unmatched'=>'تطبیق‌نشده','ambiguous'=>'مبهم','manual_review'=>'نیازمند بررسی'];?>
<nav class="subnav"><a class="<?= !$unmatched?'active':'' ?>" href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/sms')) ?>">همه پیامک‌ها</a><a class="<?= $unmatched?'active':'' ?>" href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/unmatched')) ?>">تطبیق‌نشده‌ها</a><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/reviews')) ?>">بررسی دستی</a></nav>
<section class="panel"><div class="panel-head"><div><h2><?= $unmatched?'پیامک‌های نیازمند توجه':'پیامک‌های بانکی' ?></h2><p>متن پیامک روی سرور خوانده و به پرداخت مربوط متصل می‌شود.</p></div></div><div class="table-wrap"><table><thead><tr><th>زمان</th><th>فرستنده</th><th>مبلغ واریز</th><th>خواندن پیامک</th><th>نتیجه</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty"><?= $unmatched?'موردی نیازمند بررسی نیست.':'هنوز پیامکی دریافت نشده است.' ?></div></td></tr><?php else:foreach($rows as$row):?><tr><td><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row['received_at'],(string)($settings['timezone']??'Asia/Tehran'))) ?><small><?= \CardPay\Core\View::e($row['device_name']) ?></small></td><td><?= \CardPay\Core\View::e($row['sender']?:'نامشخص') ?></td><td><?= $row['parsed_amount']?number_format((int)$row['parsed_amount']).' ریال':'—' ?></td><td><span class="badge neutral"><?= \CardPay\Core\View::e($parseLabels[$row['parse_status']]??$row['parse_status']) ?></span></td><td><span class="badge <?= $row['match_status']==='matched'?'success':'warning' ?>"><?= \CardPay\Core\View::e($matchLabels[$row['match_status']]??$row['match_status']) ?></span></td><td><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/sms/'.$row['id'])) ?>">مشاهده متن</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
